'use client'

function iconoTransprensa(estado: string): string {
  const e = (estado || '').toUpperCase()
  if (e.includes('ENTREGADO'))                          return '🟢'
  if (e.includes('DISTRIBUCION'))                       return '🔵'
  if (e.includes('EN BODEGA DESTINO'))                  return '🟡'
  if (e.includes('NOVEDAD'))                            return '🔴'
  return '🚛'
}

import { useSession } from 'next-auth/react'
import { useState, useEffect, useRef } from 'react'
import { useRouter } from 'next/navigation'
import TabsNav from '@/components/TabsNav'
import { SyncIcon } from '@/components/SyncIcon'

const BORDER: Record<string, string> = {
  pendiente:   'border-l-amber-400',
  alistado:    'border-l-emerald-500',
  en_entrega:  'border-l-blue-500',
  en_transito: 'border-l-zinc-500',
  entregado:   'border-l-zinc-600',
}

const BADGE: Record<string, string> = {
  pendiente:   'bg-amber-500/15 text-amber-400 border-amber-500/30',
  alistado:    'bg-emerald-500/15 text-emerald-400 border-emerald-500/30',
  en_entrega:  'bg-blue-500/15 text-blue-400 border-blue-500/30',
  en_transito: 'bg-zinc-500/15 text-zinc-400 border-zinc-500/30',
  entregado:   'bg-zinc-700/30 text-zinc-500 border-zinc-700/30',
}

const LABEL: Record<string, string> = {
  pendiente: 'Pendiente', alistado: 'Alistado', en_entrega: 'En entrega',
  en_transito: 'En tránsito', entregado: 'Entregado',
}

function formatHora(iso: string | null | undefined) {
  if (!iso) return ''
  const d = new Date(iso)
  return d.toLocaleTimeString('es-CO', { hour: '2-digit', minute: '2-digit', hour12: true, timeZone: 'America/Bogota' })
}

function nombreCorto(n: string) {
  const parts = n.trim().split(' ')
  const result = parts.slice(0, 3).join(' ')
  return result.length > 22 ? result.slice(0, 22) + '…' : result
}
function formatFechaCorta(iso: string | null | undefined) {
  if (!iso) return ''
  const d = new Date(new Date(iso).getTime() - 5*60*60*1000) // UTC-5 Bogotá
  const dd = String(d.getUTCDate()).padStart(2,'0')
  const mm = String(d.getUTCMonth()+1).padStart(2,'0')
  const yy = String(d.getUTCFullYear()).slice(2)
  const h = d.getUTCHours() % 12 || 12
  const min = String(d.getUTCMinutes()).padStart(2,'0')
  const ampm = d.getUTCHours() >= 12 ? 'pm' : 'am'
  return dd+'/'+mm+'/'+yy+' '+h+':'+min+ampm
}

export default function BodegaPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const user = session?.user as any

  const [tab, setTab] = useState<'despachos' | 'inventario'>('despachos')
  const [subTab, setSubTab] = useState<'pendientes' | 'alistados' | 'entregados'>('pendientes')
  const [cursores, setCursores] = useState<Record<string, string | null>>({ pendiente: null, alistado: null, despachado: null })
  const [hayMasPorTab, setHayMasPorTab] = useState<Record<string, boolean>>({ pendiente: false, alistado: false, despachado: false })
  const [despachosPorTab, setDespachosPorTab] = useState<Record<string, any[]>>({ pendiente: [], alistado: [], despachado: [] })
  const [cargandoMasTab, setCargandoMasTab] = useState(false)
  const [ciudadLocal, setCiudadLocal] = useState<string | null>(null)
  const [bodegaPuedeEnviar, setBodegaPuedeEnviar] = useState(false)
  const [repartidores, setRepartidores] = useState<any[]>([])
  const [cargando, setCargando] = useState(true)
  const [syncing, setSyncing] = useState(false)
  const [msgSync, setMsgSync] = useState('')
  const [origenSel, setOrigenSel] = useState('propia')
  const [filtroEnvio, setFiltroEnvio] = useState<'todos' | 'local' | 'guia'>('todos')
  const [diasHistorial, setDiasHistorial] = useState<number>(() => { if (typeof window === 'undefined') return 10; const v = parseInt(localStorage.getItem('diasHistorialVista') || '10'); return Math.min(30, Math.max(1, v)) })

  function cambiarDias(delta: number) {
    const nuevo = Math.min(30, Math.max(1, diasHistorial + delta))
    setDiasHistorial(nuevo)
    try { localStorage.setItem('diasHistorialVista', String(nuevo)) } catch {}
  }
  const [empresasOrigen, setEmpresasOrigen] = useState<any[]>([])
  const [saving, setSaving] = useState<Record<string, boolean>>({})
  const [expanded, setExpanded] = useState<Record<string, boolean>>({})
  const [editTransporte, setEditTransporte] = useState<Record<string, { transportadora: string; guia: string }>>({})
  const [editRepartidor, setEditRepartidor] = useState<Record<string, string>>({})
  const [modalFoto, setModalFoto] = useState<{ url: string; fecha: string } | null>(null)
  const [fotoEntregaUrls, setFotoEntregaUrls] = useState<Record<string, string>>({})
  const [camaraActiva, setCamaraActiva] = useState(false)
  const [camaraOrdenId, setCamaraOrdenId] = useState<string | null>(null)
  const [preview, setPreview] = useState<string | null>(null)
  const [zoomLevel, setZoomLevel] = useState(1)
  const [soportaZoom, setSoportaZoom] = useState(false)
  const [asignarTodasRepartidor, setAsignarTodasRepartidor] = useState('')
  const [asignandoTodas, setAsignandoTodas] = useState(false)
  const [busqueda, setBusqueda] = useState('')
  const [ordenDesc, setOrdenDesc] = useState(true)
  const montado = useRef(false)
  const videoRef = useRef<HTMLVideoElement>(null)
  const streamRef = useRef<MediaStream | null>(null)
  const trackRef = useRef<MediaStreamTrack | null>(null)

  const esAdmin = user?.role === 'empresa' || user?.role === 'supervisor'

  useEffect(() => {
    if (status === 'unauthenticated') { router.push('/login'); return }
    if (status !== 'authenticated') return
    if (!['empresa', 'supervisor', 'bodega'].includes(user?.role)) { router.push('/inicio'); return }
    cargarDatos().then(() => { montado.current = true })
    fetch('/api/bodega/empresas-origen').then(r => r.json()).then(d => setEmpresasOrigen(Array.isArray(d) ? d : []))
    fetch('/api/empleados?rol=entregas')
      .then(r => r.json())
      .then(d => setRepartidores(d.empleados || []))
      .catch(() => {})
  }, [status])

  useEffect(() => { if (status === 'authenticated' && montado.current) cargarDatos() }, [origenSel, diasHistorial])

  const ESTADO_POR_SUBTAB: Record<'pendientes' | 'alistados' | 'entregados', 'pendiente' | 'alistado' | 'despachado'> = {
    pendientes: 'pendiente', alistados: 'alistado', entregados: 'despachado',
  }

  async function cargarTab(estadoTab: 'pendiente' | 'alistado' | 'despachado', reset = false) {
    if (reset) {
      setCursores(p => ({ ...p, [estadoTab]: null }))
      setDespachosPorTab(p => ({ ...p, [estadoTab]: [] }))
    }
    try {
      const params = new URLSearchParams()
      if (origenSel !== 'propia') params.set('origenId', origenSel)
      params.set('estado', estadoTab)
      if (!reset && cursores[estadoTab]) params.set('cursor', cursores[estadoTab]!)
      const data = await fetch(`/api/bodega/despachos?${params}`).then(r => r.json())
      setDespachosPorTab(p => ({ ...p, [estadoTab]: reset ? (data.despachos || []) : [...(p[estadoTab] || []), ...(data.despachos || [])] }))
      setCursores(p => ({ ...p, [estadoTab]: data.nextCursor || null }))
      setHayMasPorTab(p => ({ ...p, [estadoTab]: !!data.hayMas }))
      setCiudadLocal(data.ciudadLocal || null)
      setBodegaPuedeEnviar(data.bodegaPuedeEnviar ?? false)
    } catch {}
  }

  async function cargarDatos() {
    setCargando(true)
    try {
      await Promise.all([
        cargarTab('pendiente', true),
        cargarTab('alistado', true),
        cargarTab('despachado', true),
      ])
    } finally {
      setCargando(false)
    }
  }

  async function cargarMasTab() {
    const estadoTab = ESTADO_POR_SUBTAB[subTab]
    if (cargandoMasTab || !hayMasPorTab[estadoTab]) return
    setCargandoMasTab(true)
    try { await cargarTab(estadoTab) } finally { setCargandoMasTab(false) }
  }

  async function sync() {
    setSyncing(true); setMsgSync('')
    try {
      const body = origenSel !== 'propia' ? { vinculadaId: origenSel } : {}
      const res = await fetch('/api/bodega/sync', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })
      const data = await res.json()
      if (data.ok) {
        setMsgSync(`✅ ${data.sincronizados} sincronizadas`)
        await cargarDatos()
      } else {
        setMsgSync(data.error || 'Error al sincronizar')
      }
    } catch { setMsgSync('Error de conexión') }
    finally {
      setSyncing(false)
      setTimeout(() => setMsgSync(''), 4000)
    }
  }

  async function patchOrden(id: string, body: Record<string, unknown>) {
    setSaving(p => ({ ...p, [id]: true }))
    try {
      const res = await fetch(`/api/bodega/despachos/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      })
      const data = await res.json()
      if (data.orden) {
        moverEntreTabs(id, data.orden)
      }
    } finally {
      setSaving(p => ({ ...p, [id]: false }))
    }
  }

  function moverEntreTabs(id: string, ordenActualizada: any) {
    const estadoFinal = ordenActualizada.estado
    const esDespachada = ['en_entrega', 'en_transito', 'entregado'].includes(estadoFinal)
    const esAlistada = estadoFinal === 'alistado'
    setDespachosPorTab(prev => {
      const next = { ...prev }
      for (const t of Object.keys(next) as Array<'pendiente' | 'alistado' | 'despachado'>) {
        if (esDespachada && t !== 'despachado') {
          next[t] = next[t].filter((d: any) => d.id !== id)
        } else if (esDespachada && t === 'despachado') {
          const yaExiste = next[t].some((d: any) => d.id === id)
          next[t] = yaExiste
            ? next[t].map((d: any) => d.id === id ? { ...d, ...ordenActualizada } : d)
            : [{ ...ordenActualizada }, ...next[t]]
        } else if (esAlistada && t === 'pendiente') {
          next[t] = next[t].filter((d: any) => d.id !== id)
        } else if (esAlistada && t === 'alistado') {
          const yaExiste = next[t].some((d: any) => d.id === id)
          next[t] = yaExiste
            ? next[t].map((d: any) => d.id === id ? { ...d, ...ordenActualizada } : d)
            : [...next[t], { ...ordenActualizada }]
        } else {
          next[t] = next[t].map((d: any) => d.id === id ? { ...d, ...ordenActualizada } : d)
        }
      }
      return next
    })
    if (esDespachada) setSubTab('entregados')
    else if (esAlistada) setSubTab('alistados')
  }

  async function abrirCamara(ordenId: string) {
    setCamaraOrdenId(ordenId)
    setCamaraActiva(true)
    setPreview(null)
    const stream = await navigator.mediaDevices.getUserMedia({
      video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } },
    })
    streamRef.current = stream
    const track = stream.getVideoTracks()[0]
    trackRef.current = track
    setZoomLevel(1)
    const capabilities = track.getCapabilities() as any
    setSoportaZoom(!!capabilities.zoom)
    if (videoRef.current) videoRef.current.srcObject = stream
  }

  async function aplicarZoom(nivel: number) {
    const track = trackRef.current
    if (!track) return
    const capabilities = track.getCapabilities() as any
    const min = capabilities.zoom?.min ?? 1
    const max = capabilities.zoom?.max ?? 5
    const nuevo = Math.min(max, Math.max(min, nivel))
    await track.applyConstraints({ advanced: [{ zoom: nuevo } as any] })
    setZoomLevel(nuevo)
  }

  function capturarFoto() {
    const video = videoRef.current
    if (!video || !video.videoWidth) return
    const canvas = document.createElement('canvas')
    canvas.width = video.videoWidth
    canvas.height = video.videoHeight
    canvas.getContext('2d')!.drawImage(video, 0, 0)
    const base64 = canvas.toDataURL('image/jpeg', 0.7)
    streamRef.current?.getTracks().forEach(t => t.stop())
    setPreview(base64)
  }

  async function usarFoto() {
    if (!preview || !camaraOrdenId) return
    setSaving(p => ({ ...p, [camaraOrdenId]: true }))
    try {
      const res = await fetch('/api/bodega/foto', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ordenId: camaraOrdenId, fotoBase64: preview }),
      }).then(r => r.json())
      if (res.orden) moverEntreTabs(camaraOrdenId, res.orden)
    } finally {
      setSaving(p => ({ ...p, [camaraOrdenId!]: false }))
      setCamaraActiva(false)
      setCamaraOrdenId(null)
      setPreview(null)
    }
  }

  function cerrarCamara() {
    streamRef.current?.getTracks().forEach(t => t.stop())
    setCamaraActiva(false)
    setCamaraOrdenId(null)
    setPreview(null)
  }

  async function abrirFotoEntrega(ordenId: string, key: string, fecha: string) {
    if (fotoEntregaUrls[ordenId]) {
      setModalFoto({ url: fotoEntregaUrls[ordenId], fecha })
      return
    }
    try {
      const res = await fetch('/api/firma', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ firma: key }) })
      const data = await res.json()
      const url = data.url || key
      setFotoEntregaUrls(p => ({ ...p, [ordenId]: url }))
      setModalFoto({ url, fecha })
    } catch { setModalFoto({ url: key, fecha }) }
  }

  function toggleExpanded(id: string) {
    setExpanded(p => ({ ...p, [id]: !p[id] }))
  }

  async function marcarAlistado(id: string) {
    await patchOrden(id, { estado: 'alistado' })
  }

  async function asignarRepartidor(id: string) {
    const rid = editRepartidor[id]
    if (!rid) return
    await patchOrden(id, { repartidorId: rid, estado: 'en_entrega' })
    setEditRepartidor(p => { const n = { ...p }; delete n[id]; return n })
    setExpanded(p => ({ ...p, [id]: false }))
  }

  async function asignarTodas() {
    if (!asignarTodasRepartidor) return
    setAsignandoTodas(true)
    const alistadas = despachosPorTab['alistado'] || []
    for (const d of alistadas) {
      await patchOrden(d.id, { repartidorId: asignarTodasRepartidor, estado: 'en_entrega' })
    }
    setAsignandoTodas(false)
    setAsignarTodasRepartidor('')
  }

  async function guardarTransporte(id: string) {
    const t = editTransporte[id]
    if (!t) return
    await patchOrden(id, { transportadora: t.transportadora, guiaTransporte: t.guia, estado: 'en_transito' })
    setEditTransporte(p => { const n = { ...p }; delete n[id]; return n })
    setExpanded(p => ({ ...p, [id]: false }))
  }

  const tabs = [
    { id: 'despachos', label: '📦 Despachos' },
    { id: 'inventario', label: '🗄️ Inventario' },
  ]

  if (status === 'loading' || cargando) {
    return (
      <div className="flex items-center justify-center py-20">
        <span className="w-6 h-6 border-2 border-blue-500/30 border-t-blue-500 rounded-full animate-spin" />
      </div>
    )
  }

  const puedeEnviar = esAdmin || bodegaPuedeEnviar

  return (
    <div className="max-w-2xl mx-auto space-y-4">
      <div className="flex items-center justify-between gap-2">
        <div>
          <h1 className="text-2xl font-bold text-white">Bodega</h1>
          <p className="text-zinc-400 text-sm mt-0.5">Gestión de despachos y alistamiento</p>
        </div>
        <div className="flex items-center gap-2 flex-shrink-0">
          <div className="flex items-center gap-1  rounded-xl px-1 py-1" style={{background:"#0d1220",border:"1px solid #1e2a3d"}}>
            <button onClick={() => cambiarDias(-1)} disabled={diasHistorial <= 1}
              className="w-6 h-6 flex items-center justify-center text-zinc-400 hover:text-white disabled:opacity-30 text-sm font-bold">−</button>
            <span className="text-white text-xs font-semibold w-8 text-center">{diasHistorial}d</span>
            <button onClick={() => cambiarDias(1)} disabled={diasHistorial >= 30}
              className="w-6 h-6 flex items-center justify-center text-zinc-400 hover:text-white disabled:opacity-30 text-sm font-bold">+</button>
          </div>
          <button onClick={() => setOrdenDesc(v => !v)}
            className="flex items-center justify-center rounded-xl px-2 py-1 text-white text-sm font-bold"
            style={{background:"#0d1220",border:"1px solid #1e2a3d"}}
            title={ordenDesc ? 'Más reciente primero' : 'Más antiguo primero'}>
            {ordenDesc ? '🔻' : '🔺'}
          </button>
          <button onClick={sync} disabled={syncing}
            className={`flex items-center gap-1.5 bg-zinc-800 hover:bg-zinc-700 disabled:opacity-40 text-zinc-300 border border-zinc-700 font-semibold px-3 py-1.5 rounded-xl text-xs transition-colors ${syncing ? 'btn-shimmer' : ''}`}>
            <SyncIcon spinning={syncing} className="w-3.5 h-3.5 text-blue-400" />
            {syncing ? '...' : 'Sync'}
          </button>
        </div>
      </div>

      <TabsNav tabs={tabs} active={tab} onChange={(t: any) => setTab(t)} />

      {tab === 'despachos' && (
        <div className="space-y-2">
          {/* Sub-tabs */}
          {(() => {
            const cPendientes = despachosPorTab['pendiente']?.length || 0
            const cAlistados  = despachosPorTab['alistado']?.length || 0
            const cEntregados = despachosPorTab['despachado']?.length || 0
            const pills: { id: typeof subTab; label: string; count: number; active: string; inactive: string; badge: string }[] = [
              { id: 'pendientes', label: 'Pendientes', count: cPendientes,
                active: 'bg-amber-500 border-amber-500 text-white',
                inactive: 'bg-zinc-800 border-zinc-700 text-amber-400 hover:bg-zinc-700',
                badge: 'bg-amber-600/60' },
              { id: 'alistados',  label: 'Alistados',  count: cAlistados,
                active: 'bg-emerald-600 border-emerald-600 text-white',
                inactive: 'bg-zinc-800 border-zinc-700 text-emerald-400 hover:bg-zinc-700',
                badge: 'bg-emerald-700/60' },
              { id: 'entregados', label: 'Entregados', count: cEntregados,
                active: 'bg-blue-600 border-blue-600 text-white',
                inactive: 'bg-zinc-800 border-zinc-700 text-blue-400 hover:bg-zinc-700',
                badge: 'bg-blue-700/60' },
            ]
            return (
              <div className="flex gap-2">
                {pills.map(p => (
                  <button key={p.id} onClick={() => setSubTab(p.id)}
                    className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold border transition-colors ${
                      subTab === p.id ? p.active : p.inactive
                    }`}>
                    {p.label}
                    <span className={`rounded-full px-1.5 py-0.5 text-[10px] font-bold text-white ${p.badge}`}>{p.count}</span>
                  </button>
                ))}
              </div>
            )
          })()}

          {/* Filtro local / guía */}
          {ciudadLocal && (
            <div className="flex gap-2">
              {([
                { id: 'todos',  label: 'Todos' },
                { id: 'local',  label: '🏠 Local' },
                { id: 'guia',   label: '🚛 Guía' },
              ] as const).map(f => (
                <button key={f.id} onClick={() => setFiltroEnvio(f.id)}
                  className={`px-3 py-1 rounded-xl text-xs font-semibold border transition-colors ${
                    filtroEnvio === f.id
                      ? 'bg-indigo-600 border-indigo-600 text-white'
                      : 'bg-zinc-800 border-zinc-700 text-zinc-400 hover:bg-zinc-700'
                  }`}>
                  {f.label}
                </button>
              ))}
            </div>
          )}

          {/* Selector empresa */}
          {empresasOrigen.length > 1 && (
            <select value={origenSel} onChange={e => setOrigenSel(e.target.value)}
              className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2 text-white text-sm mb-3">
              {empresasOrigen.map((e: any) => (
                <option key={e.id} value={e.id}>{e.nombre}</option>
              ))}
            </select>
          )}
          {/* Contador + Sync */}
          <div className="flex items-center justify-between gap-2">
            <p className="text-zinc-300 text-xs">{(despachosPorTab[ESTADO_POR_SUBTAB[subTab]] || []).length} orden{(despachosPorTab[ESTADO_POR_SUBTAB[subTab]] || []).length !== 1 ? 'es' : ''}{msgSync && <span className="ml-2 text-emerald-400">{msgSync}</span>}</p>
            <button onClick={sync} disabled={syncing}
              className={`flex items-center gap-1.5 bg-zinc-800 hover:bg-zinc-700 disabled:opacity-40 text-zinc-300 border border-zinc-700 font-semibold px-3 py-1.5 rounded-xl text-xs transition-colors ${syncing ? 'btn-shimmer' : ''}`}>
              <SyncIcon spinning={syncing} className="w-3.5 h-3.5 text-blue-400" />
              {syncing ? '...' : 'Sync'}
            </button>
          </div>

          {(despachosPorTab[ESTADO_POR_SUBTAB[subTab]] || []).length === 0 ? (
            <div className="bg-zinc-900 border border-zinc-800 rounded-2xl px-5 py-10 text-center">
              <p className="text-zinc-300 text-sm">Sin órdenes en el período configurado</p>
            </div>
          ) : (() => {
            const despachosRaw = despachosPorTab[ESTADO_POR_SUBTAB[subTab]] || []
            const q = busqueda.toLowerCase().trim()
            const despachosVisibles = despachosRaw
              .filter((d: any) => {
                if (filtroEnvio !== 'todos') {
                  const esLocal = ciudadLocal && d.ciudad &&
                    d.ciudad.split('/').pop()?.trim().toLowerCase() === ciudadLocal.trim().toLowerCase()
                  if (filtroEnvio === 'local' && !esLocal) return false
                  if (filtroEnvio === 'guia' && esLocal) return false
                }
                if (!q) return true
                return (
                  d.cliente?.toLowerCase().includes(q) ||
                  d.factura?.toLowerCase().includes(q) ||
                  d.guia?.toLowerCase().includes(q) ||
                  d.ciudad?.toLowerCase().includes(q) ||
                  d.repartidorNombre?.toLowerCase().includes(q)
                )
              })
              .sort((a: any, b: any) => {
                const ta = new Date(a.fechaOrden ?? a.createdAt).getTime()
                const tb = new Date(b.fechaOrden ?? b.createdAt).getTime()
                return ordenDesc ? tb - ta : ta - tb
              })
            return (
              <>
                {subTab === 'alistados' && despachosVisibles.length > 0 && puedeEnviar && (
                  <div className="flex gap-2 items-center">
                    <select value={asignarTodasRepartidor} onChange={e => setAsignarTodasRepartidor(e.target.value)}
                      className="flex-1  rounded-lg px-3 py-2 text-white text-xs" style={{background:"#0d1220",border:"1px solid #1e2a3d"}}>
                      <option value="">— Repartidor —</option>
                      {repartidores.map(r => <option key={r.id} value={r.id}>{r.nombre}</option>)}
                    </select>
                    <button onClick={asignarTodas} disabled={asignandoTodas || !asignarTodasRepartidor}
                      className="bg-blue-600 hover:bg-blue-500 disabled:opacity-40 text-white px-3 py-2 rounded-xl text-xs font-semibold">
                      {asignandoTodas ? '...' : '🚚 Asignar todas'}
                    </button>
                  </div>
                )}
                {despachosVisibles.map(d => {
              // Ciudad ya normalizada en BD
              const ciudadRaw = d.ciudad || null
              const ciudadNombre = ciudadRaw ? ciudadRaw.split('/').pop()?.trim().replace(/\b\w/g, (c: string) => c.toUpperCase()) ?? ciudadRaw : null
              const border = BORDER[d.estado] ?? BORDER.pendiente
              const badge = BADGE[d.estado] ?? BADGE.pendiente
              const label = LABEL[d.estado] ?? 'Pendiente'
              const isSaving = saving[d.id]
              const isExpanded = expanded[d.id]
              const esLocalidad = ciudadLocal && d.ciudad &&
                d.ciudad.split('/').pop()?.trim().toLowerCase() === ciudadLocal.trim().toLowerCase()
              const horaOrden = d.fechaOrden ? formatFechaCorta(d.fechaOrden) : formatFechaCorta(d.createdAt)
              const fotoKey = d.fotoAlistamiento
              const horaAlistado = formatHora(d.alistadoEl ?? d.updatedAt)

              // Botón 🖼️ hora — clicable, abre modal
              const fotoUrl = fotoKey?.startsWith('/fotos/') ? fotoKey : `/api/bodega/foto/${d.id}`
              const btnFoto = fotoKey ? (
                <button
                  onClick={() => setModalFoto({ url: fotoUrl, fecha: d.alistadoEl ?? '' })}
                  className="flex items-center gap-1 text-zinc-400 hover:text-zinc-200 transition-colors text-xs">
                  <span>🖼️</span>
                  <span>{horaAlistado}</span>
                </button>
              ) : null

              return (
                <div key={d.id} className={`bg-zinc-900 border border-zinc-800 border-l-4 ${border} rounded-2xl overflow-hidden`}>

                  {/* Cabecera una línea */}
                  <div className="px-4 py-3 flex items-center gap-2">
                    <div className="flex-1 min-w-0 flex items-center gap-1.5 overflow-hidden">
                      <span className="text-white font-mono text-xs flex-shrink-0">#{d.numeroFactura || d.numeroOrden}</span>
                      <span className="text-zinc-700 flex-shrink-0">·</span>
                      <span className="text-white font-semibold text-sm truncate flex-1">{nombreCorto(d.clienteNombre)}</span>
                    </div>

                  </div>

                  {/* Barra de acciones */}
                  {d.estado === 'pendiente' && (
                    <div className="px-4 pb-3 pt-1 flex items-center gap-2 border-t border-zinc-800/60">
                      <span className="text-white text-xs flex-shrink-0">{horaOrden}</span>
                      {fotoKey ? (
                        btnFoto
                      ) : (
                        <button onClick={() => abrirCamara(d.id)} disabled={isSaving}
                          className="flex items-center gap-1 bg-zinc-800 hover:bg-zinc-700 disabled:opacity-40 text-zinc-300 border border-zinc-700 px-3 py-1.5 rounded-xl text-xs font-semibold transition-colors">
                          📷 Foto
                        </button>
                      )}
                      <button onClick={() => marcarAlistado(d.id)} disabled={isSaving || !fotoKey}
                        className="flex items-center gap-1 bg-emerald-600 hover:bg-emerald-500 disabled:opacity-40 text-white px-3 py-1.5 rounded-xl text-xs font-semibold transition-colors">
                        {isSaving ? '⏳' : '✓ Listo'}
                      </button>
                    </div>
                  )}

                  {d.estado === 'alistado' && (
                    <div className="px-4 pb-3 pt-1 border-t border-zinc-800/60">
                      <div className="flex items-center gap-3 mt-1">
                        {btnFoto}
                        {d.devuelta && (
                          <span className="text-xs font-semibold px-1.5 py-0.5 rounded-md flex-shrink-0" style={{ color: '#f97316', background: 'rgba(249,115,22,0.12)' }}>Devuelta</span>
                        )}
                        {puedeEnviar ? (
                          <button onClick={() => toggleExpanded(d.id)}
                            className="flex items-center gap-1 bg-zinc-800 hover:bg-zinc-700 text-zinc-300 border border-zinc-700 px-3 py-1.5 rounded-xl text-xs font-semibold transition-colors">
                            🚚 Enviar {isExpanded ? '▲' : '▼'}
                          </button>
                        ) : (
                          <span className="text-zinc-300 text-xs italic">esperando envío...</span>
                        )}
                      </div>

                      {isExpanded && puedeEnviar && (
                        <div className="mt-3 space-y-3">
                          {esLocalidad ? (
                            <div className="space-y-2">
                              <p className="text-zinc-300 text-xs font-semibold">Asignar repartidor</p>
                              <div className="flex gap-2">
                                <select
                                  value={editRepartidor[d.id] ?? ''}
                                  onChange={e => setEditRepartidor(p => ({ ...p, [d.id]: e.target.value }))}
                                  className="flex-1  rounded-lg px-3 py-2 text-white text-xs outline-none focus:border-blue-500" style={{background:"#0d1220",border:"1px solid #1e2a3d"}}>
                                  <option value="">— Seleccionar —</option>
                                  {repartidores.map((r: any) => (
                                    <option key={r.id} value={r.id}>{r.nombre}</option>
                                  ))}
                                </select>
                                <button onClick={() => asignarRepartidor(d.id)}
                                  disabled={isSaving || !editRepartidor[d.id]}
                                  className="bg-blue-600 hover:bg-blue-500 disabled:opacity-40 text-white font-semibold px-3 py-2 rounded-xl text-xs transition-colors">
                                  {isSaving ? '...' : 'Asignar'}
                                </button>
                              </div>
                            </div>
                          ) : (
                            <div className="space-y-2">
                              <p className="text-zinc-300 text-xs font-semibold">Envío nacional</p>
                              <div className="grid grid-cols-2 gap-2">
                                <div>
                                  <label className="text-zinc-300 text-xs block mb-1">Transportadora</label>
                                  <input
                                    value={editTransporte[d.id]?.transportadora ?? ''}
                                    onChange={e => setEditTransporte(p => ({ ...p, [d.id]: { ...p[d.id], transportadora: e.target.value } }))}
                                    placeholder="Servientrega"
                                    className="w-full  rounded-lg px-3 py-2 text-white text-xs outline-none focus:border-orange-500" style={{background:"#0d1220",border:"1px solid #1e2a3d"}}
                                  />
                                </div>
                                <div>
                                  <label className="text-zinc-300 text-xs block mb-1"># Guía</label>
                                  <input
                                    value={editTransporte[d.id]?.guia ?? ''}
                                    onChange={e => setEditTransporte(p => ({ ...p, [d.id]: { ...p[d.id], guia: e.target.value } }))}
                                    placeholder="123456789"
                                    className="w-full  rounded-lg px-3 py-2 text-white text-xs outline-none focus:border-orange-500" style={{background:"#0d1220",border:"1px solid #1e2a3d"}}
                                  />
                                </div>
                              </div>
                              <button onClick={() => guardarTransporte(d.id)}
                                disabled={isSaving || (!editTransporte[d.id]?.transportadora && !editTransporte[d.id]?.guia)}
                                className="bg-orange-600 hover:bg-orange-500 disabled:opacity-40 text-white font-semibold px-4 py-1.5 rounded-xl text-xs transition-colors">
                                {isSaving ? 'Guardando...' : 'Confirmar envío'}
                              </button>
                            </div>
                          )}
                        </div>
                      )}
                    </div>
                  )}

                  {d.estado === 'en_entrega' && (
                    <div className="px-4 pb-3 pt-1 border-t border-zinc-800/60 flex items-center gap-3 mt-1">
                      {btnFoto}
                      <span className="text-zinc-400 text-xs">🚚 {d.repartidor?.nombre ?? '—'} · {formatHora(d.alistadoEl)}</span>
                    </div>
                  )}

                  {d.estado === 'en_transito' && (
                    <div className="px-4 pb-3 pt-1 border-t border-zinc-800/60 flex items-center gap-3 flex-wrap mt-1">
                      {btnFoto}
                      <span className="text-zinc-400 text-xs">🚛 {d.transportadora} <span className="font-mono text-zinc-500">#{d.guiaTransporte}</span></span>
                    </div>
                  )}

                  {d.estado === 'entregado' && (
                    <div className="px-4 pb-3 pt-1 border-t border-zinc-800/60 flex items-center gap-3 mt-1">
                      {d.trRawEstados?.length ? (
                        <span className="text-xs flex items-center gap-1.5 flex-1">
                          <span>{iconoTransprensa((d.trRawEstados as any[]).at(-1)?.estado_nombre ?? '')}</span>
                          <span className="text-white">{formatFechaCorta((() => { const last = (d.trRawEstados as any[]).at(-1); return last?.estado_fecha ? `${last.estado_fecha}T${last.estado_hora || '00:00:00'}-05:00` : null })())}</span>
                          <span className="text-zinc-400 truncate">{(d.trRawEstados as any[]).at(-1)?.estado_nombre}</span>
                          {d.trImagenCumplido && (
                            <button onClick={() => window.open(d.trImagenCumplido, '_blank')}
                              className="text-zinc-400 hover:text-white text-base flex-shrink-0 ml-auto">📝</button>
                          )}
                        </span>
                      ) : (
                        <span className="text-emerald-500 text-xs flex items-center gap-1.5">
                          ✅ Entregado {formatFechaCorta(d.entregadoEl)}
                          {d.fotoEntrega && (
                            <button
                              onClick={() => abrirFotoEntrega(d.id, d.fotoEntrega, d.entregadoEl ?? '')}
                              className="flex items-center gap-1 text-zinc-400 hover:text-zinc-200 transition-colors text-xs ml-1">
                              📷
                            </button>
                          )}
                        </span>
                      )}
                    </div>
                  )}
                </div>
              )
            })}
              </>
            )
          })()}

          {hayMasPorTab[ESTADO_POR_SUBTAB[subTab]] && (
            <button onClick={cargarMasTab} disabled={cargandoMasTab}
              className="w-full bg-zinc-900 border border-zinc-800 text-zinc-400 text-xs font-semibold py-3 rounded-2xl hover:text-white disabled:opacity-40 transition-colors">
              {cargandoMasTab ? 'Cargando...' : 'Cargar más'}
            </button>
          )}
        </div>
      )}

      {tab === 'inventario' && (
        <div className="bg-zinc-900 border border-zinc-800 rounded-2xl px-5 py-10 text-center">
          <p className="text-zinc-300 text-sm">Próximamente</p>
        </div>
      )}

      {/* Modal cámara fullscreen */}
      {camaraActiva && (
        <div className="fixed inset-0 bg-black z-50 flex flex-col overflow-hidden touch-none">
          {!preview ? (
            <>
              <video ref={videoRef} autoPlay playsInline className="flex-1 object-cover w-full" style={{ touchAction: 'pinch-zoom' }} />
              <div className="fixed bottom-0 left-0 right-0 p-6 flex items-center justify-between bg-black/80 z-10">
                <button onClick={cerrarCamara} className="text-white text-sm">✕ Cancelar</button>
                <button onClick={capturarFoto} className="w-16 h-16 rounded-full bg-white border-4 border-zinc-400" />
                {soportaZoom ? (
                  <div className="flex items-center gap-2">
                    <button onClick={() => aplicarZoom(zoomLevel - 0.5)}
                      className="w-10 h-10 rounded-full bg-zinc-700 text-white text-xl">−</button>
                    <span className="text-white text-xs w-8 text-center">{zoomLevel.toFixed(1)}x</span>
                    <button onClick={() => aplicarZoom(zoomLevel + 0.5)}
                      className="w-10 h-10 rounded-full bg-zinc-700 text-white text-xl">+</button>
                  </div>
                ) : (
                  <div className="w-16" />
                )}
              </div>
            </>
          ) : (
            <div className="fixed inset-0 bg-black z-50 flex flex-col">
              <img src={preview} className="flex-1 w-full object-contain" />
              <div className="fixed bottom-0 left-0 right-0 p-6 flex gap-4 bg-black/80">
                <button onClick={() => { setPreview(null); abrirCamara(camaraOrdenId!) }}
                  className="flex-1 bg-zinc-800 text-white py-3 rounded-xl">🔄 Repetir</button>
                <button onClick={usarFoto}
                  className="flex-1 bg-emerald-600 text-white py-3 rounded-xl font-semibold">✓ Usar foto</button>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Modal foto grande */}
      {modalFoto && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/95 p-4"
          onClick={() => setModalFoto(null)}>
          <div className="relative max-w-sm w-full" onClick={e => e.stopPropagation()}>
            <img src={modalFoto.url} alt="Foto alistamiento"
              className="w-full rounded-2xl object-contain max-h-[70vh]" />
            {modalFoto.fecha && (
              <p className="text-zinc-400 text-xs text-center mt-2">
                Alistado: {formatFechaCorta(modalFoto.fecha)}
              </p>
            )}
            <button onClick={() => setModalFoto(null)}
              className="absolute top-2 right-2 bg-black/50 text-white rounded-full w-8 h-8 flex items-center justify-center text-sm hover:bg-black/70">
              ✕
            </button>
          </div>
        </div>
      )}
    </div>
  )
}
